34	/**
35	 * Exits Mocha when Mocha itself has finished execution, regardless of
36	 * what the tests or code under test is doing.
37	 * @param {number} clampedCode - Exit code; typically # of failures
38	 * @ignore
39	 * @private
40	 */
41	const exitMocha = clampedCode => {
42	  let draining = 0;
43	
44	  // Eagerly set the process's exit code in case stream.write doesn't
45	  // execute its callback before the process terminates.
46	  process.exitCode = clampedCode;
47	
48	  // flush output for Node.js Windows pipe bug
49	  // https://github.com/joyent/node/issues/6247 is just one bug example
50	  // https://github.com/visionmedia/mocha/issues/333 has a good discussion
51	  const done = () => {
52	    if (!draining--) {
53	      process.exit(clampedCode);
54	    }
55	  };
56	
57	  const streams = [process.stdout, process.stderr];
58	
59	  streams.forEach(stream => {
60	    // submit empty write request and wait for completion
61	    draining += 1;
62	    stream.write('', done);
63	  });
64	
65	  done();
66	};
