86	exports.handleRequires = async (requires = [], {ignoredPlugins = []} = {}) => {
87	  const pluginLoader = PluginLoader.create({ignore: ignoredPlugins});
88	  for await (const mod of requires) {
89	    let modpath = mod;
90	    // this is relative to cwd
91	    if (fs.existsSync(mod) || fs.existsSync(`${mod}.js`)) {
